from vllm import LLM, SamplingParamsmodel = "/root/autodl-tmp/models/Qwen/Qwen2.5-0.5B-Instruct"llm = LLM(    model=model,    max_model_len=4096,    enforce_eager=True,    enable_prefix_caching=False,    enable_chunked_prefill=False,    gpu_memory_utilization=0.85,)prompts = [    "Hello, my name is",    "The capital of France is",]sampling_params = SamplingParams(    temperature=0,    max_tokens=64,)outputs = llm.generate(prompts, sampling_params)for output in outputs:    print("=" * 80)    print("Prompt:", output.prompt)    print("Output:", output.outputs[0].text)